  void preview(){if(preview==null)return;List<Entry> entries=draft.entries(snapshot);if(snapshotLoading&&snapshot.movies.isEmpty()&&snapshot.shows.isEmpty()){preview.setText("Loading indexed library…");return;}if(snapshotFailed&&snapshot.movies.isEmpty()&&snapshot.shows.isEmpty()){preview.setText("Could not load the indexed library. Your page settings are kept; reopen to retry.");return;}StringBuilder text=new StringBuilder(snapshotFailed?"Could not refresh. Showing cached indexed results.\n\n":"").append(draft.name).append("\n\n").append(PreviewLibrarySummary.describe(getContext(),snapshot,entries)).append("\n");if(entries.isEmpty())text.append("\nNo matching indexed items.");else text.append("\nShowing ").append(Math.min(20,entries.size())).append(" of ").append(entries.size()).append(" matching items.\n");for(int i=0;i<Math.min(20,entries.size());i++)text.append("\n").append(PreviewPages.displayName(entries.get(i)));preview.setText(text);}
